const std = @import("std");
const Window = @import("./basics.zig").Window;

pub const SetupRequest = extern struct {
    byte_order: u8 = 'l',
    pad_1: u8 = 0,
    protocol_major_version: u16 = 11,
    protocol_minor_version: u16 = 0,
    authorization_protocol_name_len: u16 = 0,
    authorization_protocol_data_len: u16 = 0,
    pad_2: [2]u8 = .{ 0, 0 },
};

pub const ImageOrder = enum(u8) {
    LSBFirst = 0,
    MSBFirst = 1,
};

pub const Format = extern struct {
    depth: u8,
    bits_per_pixel: u8,
    scanline_pad: u8,
    pad_1: [5]u8,
};

pub const EventMask = packed struct(u32) {
    KeyPress: u1 = 0,
    KeyRelease: u1 = 0,
    ButtonPress: u1 = 0,
    ButtonRelease: u1 = 0,
    EnterWindow: u1 = 0,
    LeaveWindow: u1 = 0,
    PointerMotion: u1 = 0,
    PointerMotionHint: u1 = 0,
    Button1Motion: u1 = 0,
    Button2Motion: u1 = 0,
    Button3Motion: u1 = 0,
    Button4Motion: u1 = 0,
    Button5Motion: u1 = 0,
    ButtonMotion: u1 = 0,
    KeymapState: u1 = 0,
    Exposure: u1 = 0,
    VisibilityChange: u1 = 0,
    StructureNotify: u1 = 0,
    ResizeRedirect: u1 = 0,
    SubstructureNotify: u1 = 0,
    SubstructureRedirect: u1 = 0,
    FocusChange: u1 = 0,
    PropertyChange: u1 = 0,
    ColorMapChange: u1 = 0,
    OwnerGrabButton: u1 = 0,
    _: u7 = 0,
};

pub const BackingStore = enum(u8) {
    NotUseful = 0,
    WhenMapped = 1,
    Always = 2,
};

pub const BOOL = enum(u8) {
    FALSE = 0,
    TRUE = 1,
};

pub const VisualType = extern struct {
    visual_id: u32,
    class: VisualClass,
    bits_per_rgb_value: u8,
    colormap_entries: u16,
    red_mask: u32,
    green_mask: u32,
    blue_mask: u32,
    pad_1: [4]u8,
};

pub const VisualClass = enum(u8) {
    StaticGray = 0,
    GrayScale = 1,
    StaticColor = 2,
    PseudoColor = 3,
    TrueColor = 4,
    DirectColor = 5,
};

pub const Depth = extern struct {
    name: u8,
    pad_1: u8,
    visuals_len: u16,
    pad_2: [4]u8,

    pub fn visuals(self: *const @This()) ![]const VisualType {
        const base: [*]const u8 = @ptrCast(self);
        const start: usize = @sizeOf(@This());
        const ptr: [*]const VisualType = @ptrCast(@alignCast(base + start));
        if (@intFromPtr(ptr) > end_addr) return error.OverFlow;
        return ptr[0..self.visuals_len];
    }
    // fn end_ptr(self: *const @This()) usize {
    //     return @intFromPtr(self) + @sizeOf(@This()) + (@sizeOf(VisualType) * @as(usize, self.visuals_len));
    // }
    fn end_ptr_checked(self: *const @This()) !usize {
        const end = @intFromPtr(self) + @sizeOf(@This()) + (@sizeOf(VisualType) * @as(usize, self.visuals_len));
        if (end > end_addr) return error.OverFlow;
        return end;
    }
};

fn Iterator(t: type) type {
    return struct {
        count: u16,
        cursor: [*]const u8,
        // fn next(self: *@This()) ?*const t {
        //     if (self.count == 0) return null;
        //     self.count -= 1;
        //     const one: *const t = @ptrCast(@alignCast(self.cursor));
        //     self.cursor = @ptrFromInt(one.end_ptr());
        //     return one;
        // }
        fn next(self: *@This()) !?*const t {
            if (self.count == 0) return null;
            const out_of_bound: bool = @intFromPtr(self.cursor + @sizeOf(t)) > end_addr;
            if (out_of_bound)
                return error.OverFlow;
            self.count -= 1;
            const one: *const t = @ptrCast(@alignCast(self.cursor));
            self.cursor = @ptrFromInt(try one.end_ptr_checked());
            return one;
        }
    };
}

pub const Screen = extern struct {
    root: Window,
    default_colormap: u32,
    white_pixel: u32,
    black_pixel: u32,
    current_input_masks: EventMask,
    width_in_pixels: u16,
    height_in_pixels: u16,
    width_in_millimeters: u16,
    height_in_millimeters: u16,
    min_installed_maps: u16,
    max_installed_maps: u16,
    root_visual: u32,
    backing_stores: BackingStore,
    save_unders: BOOL,
    root_depth: u8,
    allowed_depths_len: u8,
    pub fn allowed_depths(self: *const @This()) !Iterator(Depth) {
        const base: [*]const u8 = @ptrCast(self);
        const offset: usize = @sizeOf(@This());

        const ptr: [*]const u8 = base + offset;
        if (@intFromPtr(ptr) > end_addr) return error.OverFlow;
        const iter: Iterator(Depth) = .{ .count = self.allowed_depths_len, .cursor = ptr };
        return iter;
    }
    // fn end_ptr(self: *const @This()) usize {
    //     var iter = self.allowed_depths();
    //     while (iter.next()) |_| {}
    //     return @intFromPtr(iter.cursor);
    // }
    fn end_ptr_checked(self: *const @This()) !usize {
        var iter = try self.allowed_depths();
        while (try iter.next()) |_| {}
        if (@intFromPtr(iter.cursor) > end_addr) return error.OverFlow;
        return @intFromPtr(iter.cursor);
    }
};

pub const SetupFailed = extern struct {
    status: u8 = 0,
    reason_len: u8,
    protocol_major_version: u16,
    protocol_minor_version: u16,
    length: u16,
    pub fn from_slice(bytes: []align(4) const u8) !*const @This() {
        if (bytes.len < @sizeOf(@This())) return error.SliceTooSmall;
        return @ptrCast(bytes.ptr);
    }
    pub fn reason(self: *const @This()) ![]const u8 {
        const start: usize = @sizeOf(@This());
        const end = start + self.length * 4;

        const base: [*]const u8 = @ptrCast(self);
        if (@intFromPtr(base + end) > end_addr) return error.OverFlow;
        return base[start..end];
    }
};

pub const SetupAuthenticate = extern struct {
    status: u8 = 2,
    pad_1: [5]u8,
    length: u16,
    pub fn from_slice(bytes: []align(4) const u8) !*const @This() {
        if (bytes.len < @sizeOf(@This())) return error.SliceTooSmall;
        return @ptrCast(bytes.ptr);
    }
    pub fn reason(self: *const @This()) ![]const u8 {
        const start: usize = @sizeOf(@This());
        const end = start + self.length * 4;

        const base: [*]const u8 = @ptrCast(self);
        if (@intFromPtr(base + end) > end_addr) return error.OverFlow;
        return base[start..end];
    }
};

// check this value to avoid out of bound memory access
var packet_size: usize = 0;
var end_addr: usize = 0;
pub const SetupSuccess = extern struct {
    status: u8 = 1,
    pad_1: u8,
    protocol_major_version: u16,
    protocol_minor_version: u16,
    length: u16,
    release_number: u32,
    resource_id_base: u32,
    resource_id_mask: u32,
    motion_buffer_size: u32,
    vendor_len: u16,
    maximum_request_length: u16,
    roots_len: u8,
    pixmap_formats_len: u8,
    image_byte_order: ImageOrder,
    bitmap_format_bit_order: ImageOrder,
    bitmap_format_scanline_unit: u8,
    bitmap_format_scanline_pad: u8,
    min_keycode: u8,
    max_keycode: u8,
    pad_2: u32,
    pub fn from_slice(bytes: []align(4) const u8) !*const @This() {
        if (bytes.len < @sizeOf(@This())) return error.SliceTooSmall;
        return @ptrCast(bytes.ptr);
    }
    pub fn vendor(self: *const @This()) ![]const u8 {
        const start: usize = @sizeOf(@This());
        const end = try self.vendor_end();
        const base: [*]const u8 = @ptrCast(self);
        return base[start..end];
    }
    fn vendor_end(self: *const @This()) !usize {
        const start: usize = @sizeOf(@This());
        const end = start + self.vendor_len;
        if (end > packet_size) return error.OverFlow;
        return end;
    }
    pub fn pixmap_formats(self: *const @This()) ![]const Format {
        const start = try self.vendor_end();
        _ = try self.pixmap_formats_end();
        const base: [*]const u8 = @ptrCast(self);
        const ptr: [*]const Format = @ptrCast(base + start);
        return ptr[0..self.pixmap_formats_len];
    }
    fn pixmap_formats_end(self: *const @This()) !usize {
        var start = try self.vendor_end();
        start = std.mem.alignForward(usize, start, 4);
        const end = start + (@sizeOf(Format) * @as(usize, self.pixmap_formats_len));
        if (end > packet_size) return error.OverFlow;
        return end;
    }
    pub fn screens(self: *const @This()) !Iterator(Screen) {
        const start = try self.pixmap_formats_end();

        const base: [*]const u8 = @ptrCast(self);
        const ptr: [*]const u8 = base + start;
        return .{ .count = self.roots_len, .cursor = ptr };
    }
};

const SetupReplyStatus = enum(u8) {
    Failed = 0,
    Success = 1,
    Authenticate = 2,
    pub fn from_byte(byte: u8) !@This() {
        if (byte > 2) return error.InvalidEnumValue;
        return @enumFromInt(byte);
    }
};

